'use strict';

// MODULES //

var constantFunction = require( '@stdlib/utils/constant-function' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var ln = require( '@stdlib/math/base/special/ln' );
var erf = require( '@stdlib/math/base/special/erf' );
var sqrt = require( '@stdlib/math/base/special/sqrt' );
var NINF = require( '@stdlib/constants/float64/ninf' );


// MAIN //

/**
* Returns a function for evaluating the natural logarithm of the cumulative distribution function (CDF) for a half-normal distribution.
*
* @param {PositiveNumber} sigma - scale parameter
* @returns {Function} function to evaluate the natural logarithm of the cumulative distribution function
*
* @example
* var logcdf = factory( 2.0 );
* var y = logcdf( 1.0 );
* // returns -0.9599163336956225
*
* y = logcdf( 0.0 );
* // returns -Infinity
*/
function factory( sigma ) {
	var denom;
	if (
		isnan( sigma ) ||
		sigma < 0.0
	) {
		return constantFunction( NaN );
	}
	if ( sigma === 0.0 ) {
		return logcdf;
	}
	denom = sigma * sqrt( 2.0 );
	return logcdf;

	/**
	* Evaluates the natural logarithm of the cumulative distribution function (CDF) for a half-normal distribution.
	*
	* @private
	* @param {number} x - input value
	* @returns {number} evaluated natural logarithm of CDF
	*
	* @example
	* var y = logcdf( 2.0 );
	* // returns <number>
	*/
	function logcdf( x ) {
		if ( isnan( x ) ) {
			return NaN;
		}
		if ( x < 0.0 ) {
			return NINF;
		}
		if ( sigma === 0.0 ) {
			return ( x >= 0.0 ) ? 0.0 : NINF;
		}
		return ln( erf( x / denom ) );
	}
}


// EXPORTS //

module.exports = factory;
